out.innerHTML='<div class="gl" style="grid-template-columns:repeat(auto-fill,minmax(370px,1fr))">'+T.slice(0,36).map(function(t){
 var st5=(t.rot||[]).slice(0,5),bn=(t.rot||[]).slice(5,10);
