  +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">'
  +'<div>'+(t.ap?'<span class="ap-tag">#'+t.ap+'</span>':'')+CBB.logo(t.id,22)+' <a href="team.html?id='+t.id+'" style="color:inherit;font-size:15px"><b>'+E(t.team)+'</b></a> <span class="mut sm">'+E(t.conf)+' ('+(t.rot||[]).length+' players)</span></div>'
  +'<a href="team.html?id='+t.id+'" class="chip sm" style="text-decoration:none;font-size:11px">Full Roster →</a></div>'
  +'<div style="font-size:10.5px;font-weight:800;color:#8ee04a;text-transform:uppercase;letter-spacing:.04em;margin:6px 0 4px">★ Projected Starting 5</div>'
  +'<table style="font-size:12px"><tr><th>Slot</th><th>Starter &amp; Badges</th><th>Min</th><th>USG%</th><th>Proj P/R/A</th></tr>'
  +st5.map(function(p){
   var tags=(p.is_star?' <span class="star-pill">⭐</span>':'')+(p.nba_prospect?' <span class="nba-pill '+(p.nba_tier==="NBA Lottery"?"lot":"")+'">🏀 '+E(p.nba_tier==="NBA Lottery"?"LOT":"NBA")+'</span>':'')+(p.origin==="Transfer"?' <span class="role-pill tr" title="From '+E(p.prev_team||"")+'">⇄</span>':'');
