  +bn.map(function(p){
   var tags=(p.nba_prospect?' <span class="nba-pill">🏀</span>':'')+(p.origin==="Transfer"?' <span class="role-pill tr">⇄</span>':'');
   return '<tr><td><span class="role-pill bn">'+E(p.slot||"Rot")+'</span></td><td>'+pLink(p,t.id)+tags+'</td><td>'+p.proj_min+'</td><td>'+p.usg+'%</td><td>'+p.proj_pts+'/'+p.proj_reb+'/'+p.proj_ast+'</td></tr>';
  }).join("")+'</table>':'')
  +'</div>';
}).join("")+'</div>';

